html:
{%- set co = frappe.db.get_single_value("Weighbridge Settings", "report_company_name") or "राजदत्त ॲग्रो इंडस्ट्री" -%}
{%- set addr = frappe.db.get_single_value("Weighbridge Settings", "report_address") or "गट नं. ५८४, मु. पो. अपशिंगे (रहिमतपूर), ता. कोरेगांव - ४१५ ५११, जि. सातारा (महाराष्ट्र)" -%}
{%- set ph = frappe.db.get_single_value("Weighbridge Settings", "report_phone") or "" -%}
{%- set season = frappe.db.get_value("Cane Rate Master", {"disabled": 0, "effective_from": ["<=", doc.to_date]}, "season", order_by="effective_from desc") if doc.to_date else "" -%}
{%- set fd = "dd/MM/yyyy" -%}
{%- set t = namespace(vehicles=[]) -%}
{%- for s in doc.slips -%}{%- if s.vehicle and s.vehicle not in t.vehicles -%}{%- set t.vehicles = t.vehicles + [s.vehicle] -%}{%- endif -%}{%- endfor -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, precision=2) }}{%- endmacro -%}
{%- macro day(d) -%}{{ frappe.utils.formatdate(d, fd) if d else "" }}{%- endmacro -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
@font-face { font-family: "SlipDeva"; font-weight: normal; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Regular.ttf") format("truetype"); }
@font-face { font-family: "SlipDeva"; font-weight: bold; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Bold.ttf") format("truetype"); }
.tcb, .tcb td, .tcb th, .tcb div { font-family: "SlipDeva", "Noto Sans Devanagari", sans-serif; color: #111; }
.tcb { font-size: 12px; line-height: 1.45; }
.tcb table { width: 100%; border-collapse: collapse; }
.tcb .head { text-align: center; }
.tcb .head .nm { font-size: 17px; font-weight: bold; }
.tcb .head .ad { font-size: 10.5px; }
.tcb .title { text-align: center; font-size: 14px; font-weight: bold; text-decoration: underline; margin-top: 8px; }
.tcb .season { text-align: center; margin-bottom: 8px; }
.tcb .info td { border: none; padding: 2px 4px; vertical-align: top; }
.tcb .info .l { white-space: nowrap; width: 1%; padding-right: 10px; }
.tcb .info .v { font-weight: bold; }
.tcb .rows { margin-top: 8px; border: 1px solid #333; }
.tcb .rows th { border: 1px solid #333; padding: 4px 6px; text-align: center; font-weight: bold; }
.tcb .rows td { border-left: 1px solid #333; border-right: 1px solid #333; padding: 3px 6px; }
.tcb .rows .fill td { height: 20px; }
.tcb .foot { border: 1px solid #333; border-top: none; }
.tcb .foot td { padding: 0; vertical-align: top; border: none; }
.tcb .foot .box td { padding: 4px 6px; border: 1px solid #333; }
.tcb .foot .box { border-collapse: collapse; }
.tcb .r { text-align: right; } .tcb .c { text-align: center; } .tcb .b { font-weight: bold; }
.tcb .net td { font-weight: bold; font-size: 13.5px; }
.tcb .sign { margin-top: 40px; }
</style>
<div class="tcb">
 <div class="head">
  <div class="nm">{{ co }}</div>
  <div class="ad">{{ addr }}{% if ph %}<br>PH. NO. : {{ ph }}{% endif %}</div>
 </div>
 <div class="title">ट्रॅक्टर वाहतूक बिल</div>
 <div class="season">{{ season or "" }}</div>

 <table class="info">
  <tr><td class="l">कंत्राटदाराचे नाव</td><td class="v" style="width:45%">{{ doc.contractor_name or "" }}</td>
      <td class="l">Bill No</td><td class="v">{{ doc.name }}</td></tr>
  <tr><td class="l">कंत्राटदाराचे नंबर</td><td class="v">{{ doc.contractor or "" }}</td>
      <td class="l">Bill Date</td><td class="v">{{ day(doc.bill_date) }}</td></tr>
  <tr><td class="l">वाहनाचा नंबर</td><td class="v">{{ t.vehicles|join(", ") }}</td>
      <td class="l">From Date</td><td class="v">{{ day(doc.from_date) }}</td></tr>
  <tr><td></td><td></td><td class="l">To Date</td><td class="v">{{ day(doc.to_date) }}</td></tr>
 </table>

 <table class="rows">
  <thead><tr><th style="width:13%">दिनांक</th><th>गावाचे नाव</th><th style="width:11%">अंतर कि. मी.</th><th style="width:13%">निव्वळ टनेज</th><th style="width:12%">दर</th><th style="width:15%">एकूण रक्कम</th><th style="width:11%">डिझेल लि.</th></tr></thead>
  <tbody>
  {% for s in doc.slips %}
   <tr><td class="c">{{ day(s.slip_date) }}</td><td>{{ s.village or ("डिझेल" if not s.slip else "") }}</td>
       <td class="r">{{ "%.2f"|format(s.distance) if s.slip else "" }}</td>
       <td class="r">{{ "%.3f"|format(s.quantity or 0) if s.slip else "" }}</td>
       <td class="r">{{ money(s.rate) if s.slip else "" }}</td>
       <td class="r">{{ money(s.amount) if s.slip else "" }}</td>
       <td class="r">{{ "%g"|format(s.diesel_qty) if s.diesel_qty else "" }}</td></tr>
  {% endfor %}
  {% for i in range([10 - doc.slips|length, 1]|max) %}<tr class="fill"><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>{% endfor %}
  </tbody>
 </table>

 <table class="foot"><tr>
  <td style="width:42%">
   <table class="box">
    <tr><td style="width:45%">ॲडव्हान्स{% if doc.outstanding_advance %} (बाकी {{ money((doc.outstanding_advance or 0) - (doc.advance_deduction or 0)) }}){% endif %}</td><td class="r">{{ money(doc.advance_deduction) }}</td></tr>
    <tr><td>डिपॉझिट(10%)</td><td class="r">{{ money(doc.deposit_deduction) }}</td></tr>
    <tr><td>डिझेल ({{ "%g"|format(doc.total_diesel_qty or 0) }} लि.)</td><td class="r">{{ money(doc.other_deduction) }}</td></tr>
   </table>
  </td>
  <td>
   <table class="box">
    <tr><td style="width:24%">निव्वळ टनेज</td><td class="r b" style="width:22%">{{ "%.3f"|format(doc.total_quantity or 0) }}</td>
        <td style="width:27%">एकूण रक्कम</td><td class="r">{{ money(doc.total_amount) }}</td></tr>
    <tr><td colspan="2" rowspan="3" style="border:none"></td><td>कमिशन {{ "%g"|format(doc.commission_percent or 0) }}%</td><td class="r">{{ money(doc.commission) }}</td></tr>
    <tr><td>एकूण वसुली</td><td class="r">{{ money(doc.total_deductions) }}</td></tr>
    <tr class="net"><td>निव्वळ अदा रक्कम</td><td class="r">{{ money(doc.net_payable) }}</td></tr>
   </table>
  </td>
 </tr></table>

 {% if doc.deduction_remarks %}<div style="margin-top:6px"><b>टीप:</b> {{ doc.deduction_remarks }}</div>{% endif %}
 <div class="sign">Signature</div>
</div>
